import{_ as o,l,o as e,c as s,v as t,p as n,x as i,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"模拟退火与元启发","description":"","frontmatter":{"title":"模拟退火与元启发","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/simulated-annealing.md","filePath":"cs/simulated-annealing.md","lastUpdated":1789023840000}'),h={name:"cs/simulated-annealing.md"};function m(_,a,u,T,E,A){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="模拟退火与元启发" tabindex="-1">模拟退火与元启发 <a class="header-anchor" href="#模拟退火与元启发" aria-label="Permalink to &quot;模拟退火与元启发&quot;">​</a></h1><div class="epigraph"><p>以温度 $T$ 接受变差移动 $\\mathrm{e}^{-\\Delta/T}$，缓冷趋向低能；元启发无最坏近似比，只有实践与马尔可夫直觉。</p><footer>—— 据 Kirkpatrick, Gelatt and Vecchi, Optimization by Simulated Annealing, 1983；Metropolis 等, 1953 整理</footer></div><p>上一课<a href="/cs/local-search-max-cut">局部搜索与最大割</a>卡在局部最优。模拟退火：差移动也可能走。缺口是 Metropolis 规则与冷却，以及元启发的边界：不替代 2-近似定理。本序列近似在此结束。不写神经网络训练。下一序列模型与下界。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>状态 \\(s\\)，邻域，能量 \\(E\\)（如割的负）。\\(T\\) 高：几乎随机游走；\\(T\\to 0\\) 成贪心。冷却过快冻在差局部，过慢浪费。没有一般 \\(\\rho\\)。TSP、布局等实践常用。</p><p>缺口是「有保证 vs 无保证」，不是再证 \\(m/2\\)。</p><h3 id="不是物理课相变" tabindex="-1">不是物理课相变 <a class="header-anchor" href="#不是物理课相变" aria-label="Permalink to &quot;不是物理课相变&quot;">​</a></h3><p>Metropolis 来自统计物理。本课优化启发式。不要写配分函数证明全局最优——有限时间没有。</p><p><span class="marginnote">Kirkpatrick 等 1983。Metropolis 1953。遗传算法、禁忌搜索同类元启发，点名。后课 Misra–Gries 换流模型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义邻域（翻转、2-opt）。几何降温 \\(T\\leftarrow \\alpha T\\)。每温度若干步。多起点。</p>',11)),(e(),n(c,null,{default:i(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%B8%A9%E5%BA%A6%20T%22%5D%20--%3E%20MET%5B%22Metropolis%20%E6%8E%A5%E5%8F%97%22%5D%0A%20%20MET%20--%3E%20COOL%5B%22%E7%BC%93%E5%86%B7%22%5D%0A%20%20COOL%20--%3E%20HEU%5B%22%E5%AE%9E%E8%B7%B5%E8%A7%A3%EF%BC%8C%E6%97%A0%20%CF%81%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与局部搜索：\\(T=0\\) 即上一课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>平稳分布 \\(\\propto e^{-E/T}\\)（正则系综直觉）。慢冷若够慢则趋向最优，实践不够慢。与带权随机游走：有限图上的链。与 UCB：bandit 有遗憾界；SA 对组合邻域通常无。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写收敛定理的充分条件全文。不把 SA 当 FPTAS。后课默认：要 \\(\\rho\\) 用匹配/LP/Christofides；SA 是元启发。下一课流算法 Misra–Gries。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Metropolis 接受差步；缓冷。</li><li>无一般近似比。</li><li>与有保证的局部搜索 2-近似分工。</li><li>出处：Kirkpatrick, Gelatt and Vecchi, 1983；Metropolis 等, 1953。</li></ul>',7))])}const k=o(h,[["render",m]]);export{b as __pageData,k as default};
